using System;
using System.Collections.Generic;
using Grasshopper.Kernel;
using Grasshopper.Kernel.Types;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>One four-sided facade piece cut from a surface.</summary>
    public class FacadePanel
    {
        public FacadePanel(Point3d c0, Point3d c1, Point3d c2, Point3d c3, int index)
        {
            Corners = new[] { c0, c1, c2, c3 };
            Index = index;
            Outline = new PolylineCurve(new[] { c0, c1, c2, c3, c0 });

            // Vector area of the quad from its diagonals; also valid for non-planar quads.
            Area = 0.5 * Vector3d.CrossProduct(c2 - c0, c3 - c1).Length;
            Center = new Point3d(
                (c0.X + c1.X + c2.X + c3.X) / 4,
                (c0.Y + c1.Y + c2.Y + c3.Y) / 4,
                (c0.Z + c1.Z + c2.Z + c3.Z) / 4);

            Vector3d normal = Vector3d.CrossProduct(c1 - c0, c2 - c0);
            Deviation = normal.Unitize() ? Math.Abs((c3 - c0) * normal) : c3.DistanceTo(c0);
        }

        public Point3d[] Corners { get; }
        public PolylineCurve Outline { get; }
        public double Area { get; }
        public double Deviation { get; }
        public Point3d Center { get; }
        public int Index { get; }

        /// <summary>Edge length i runs from corner i to corner i+1.</summary>
        public double Edge(int i) => Corners[i].DistanceTo(Corners[(i + 1) % 4]);

        public double Width => (Edge(0) + Edge(2)) / 2;
        public double Height => (Edge(1) + Edge(3)) / 2;

        public double[] SortedEdges()
        {
            var e = new[] { Edge(0), Edge(1), Edge(2), Edge(3) };
            Array.Sort(e);
            return e;
        }

        public double[] SortedDiagonals()
        {
            var d = new[] { Corners[0].DistanceTo(Corners[2]), Corners[1].DistanceTo(Corners[3]) };
            Array.Sort(d);
            return d;
        }
    }

    public class PanelGoo : GH_Goo<FacadePanel>
    {
        public PanelGoo() { }
        public PanelGoo(FacadePanel panel) { Value = panel; }

        public override bool IsValid => Value != null;
        public override string TypeName => "Panel";
        public override string TypeDescription => "Four-sided facade panel";
        public override IGH_Goo Duplicate() => new PanelGoo(Value);
        public override string ToString() => Value == null ? "Null panel" : $"Panel {Value.Index} (area {Value.Area:0.###})";
    }

    public class PanelParam : GH_Param<PanelGoo>
    {
        public PanelParam()
            : base("Panel", "Panel", "Facade panel", "Facade", "Panels", GH_ParamAccess.item)
        {
        }

        public override Guid ComponentGuid => new Guid("c1a7e0b2-5d34-4f8a-9b61-2e7d0a3c8f01");
        public override GH_Exposure Exposure => GH_Exposure.hidden;
    }

    internal static class PanelAccess
    {
        public static List<FacadePanel> GetPanels(IGH_DataAccess da, int index)
        {
            var goos = new List<PanelGoo>();
            var result = new List<FacadePanel>();
            if (!da.GetDataList(index, goos)) return result;
            foreach (var g in goos)
                if (g != null && g.Value != null) result.Add(g.Value);
            return result;
        }

        public static List<PanelGoo> Wrap(IEnumerable<FacadePanel> panels)
        {
            var list = new List<PanelGoo>();
            foreach (var p in panels) list.Add(new PanelGoo(p));
            return list;
        }
    }
}
