using System;
using System.Collections.Generic;
using System.Linq;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    public class PanelizeSurfaceComponent : GH_Component
    {
        public PanelizeSurfaceComponent()
            : base("Panelize Surface", "Panelize", "Divides a surface into four-sided panels", "Facade", "Panels")
        {
        }

        public override Guid ComponentGuid => new Guid("2f6b9a10-84c3-4d57-a1e2-7b0c3d5e9f11");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddSurfaceParameter("Surface", "S", "Surface to panelize", GH_ParamAccess.item);
            pManager.AddIntegerParameter("U Count", "U", "Panels in U direction", GH_ParamAccess.item, 10);
            pManager.AddIntegerParameter("V Count", "V", "Panels in V direction", GH_ParamAccess.item, 6);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddCurveParameter("Outlines", "O", "Closed panel outlines", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            Surface surface = null;
            int uCount = 10, vCount = 6;
            if (!DA.GetData(0, ref surface)) return;
            if (!DA.GetData(1, ref uCount)) return;
            if (!DA.GetData(2, ref vCount)) return;
            if (surface == null) return;

            if (uCount < 1 || vCount < 1)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "U Count and V Count must be at least 1");
                return;
            }

            Interval du = surface.Domain(0), dv = surface.Domain(1);
            var grid = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
                for (int j = 0; j <= vCount; j++)
                    grid[i, j] = surface.PointAt(du.ParameterAt((double)i / uCount), dv.ParameterAt((double)j / vCount));

            var panels = new List<FacadePanel>();
            var outlines = new List<Curve>();
            for (int j = 0; j < vCount; j++)
                for (int i = 0; i < uCount; i++)
                {
                    var p = new FacadePanel(grid[i, j], grid[i + 1, j], grid[i + 1, j + 1], grid[i, j + 1], j * uCount + i);
                    panels.Add(p);
                    outlines.Add(p.Outline);
                }

            DA.SetDataList(0, PanelAccess.Wrap(panels));
            DA.SetDataList(1, outlines);
        }
    }

