    public class PlanarityComponent : GH_Component
    {
        public PlanarityComponent()
            : base("Planarity", "Planarity", "Measures how flat each panel is", "Facade", "Analysis")
        {
        }

        public override Guid ComponentGuid => new Guid("9b4f2e68-31d7-4a05-b8c9-1e6f7a8d0c33");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Maximum deviation for a flat panel", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Deviation", "D", "Planarity deviation per panel", GH_ParamAccess.list);
            pManager.AddBooleanParameter("Flat", "F", "True when the panel is flat", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "N", "Number of flat panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelAccess.GetPanels(DA, 0);
            double tol = 0.5;
            if (!DA.GetData(1, ref tol)) return;

            var dev = panels.Select(p => p.Deviation).ToList();
            var flat = dev.Select(d => d <= tol).ToList();
            int flatCount = flat.Count(f => f);
            int notFlat = panels.Count - flatCount;

            if (notFlat * 2 > panels.Count)
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning, $"{notFlat} of {panels.Count} panels are not flat");

            DA.SetDataList(0, dev);
            DA.SetDataList(1, flat);
            DA.SetData(2, flatCount);
        }
    }

    public class ClassifyPanelsComponent : GH_Component
    {
        public ClassifyPanelsComponent()
            : base("Classify Panels", "Classify", "Classifies panels as flat, cold-bent or custom", "Facade", "Analysis")
        {
        }

        public override Guid ComponentGuid => new Guid("4c8a5d91-62e0-4f13-97b4-a2d3e5f60744");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Flatness tolerance", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("Type", "Ty", "flat, cold-bent or custom per panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "F", "Number of flat panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Cold Bent Count", "C", "Number of cold-bent panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Custom Count", "Cu", "Number of custom panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelAccess.GetPanels(DA, 0);
            double tol = 0.5;
            if (!DA.GetData(1, ref tol)) return;

            var types = new List<string>();
            int flat = 0, bent = 0, custom = 0;
            foreach (var p in panels)
            {
                if (p.Deviation <= tol) { types.Add("flat"); flat++; }
                else if (p.Deviation <= 10 * tol) { types.Add("cold-bent"); bent++; }
                else { types.Add("custom"); custom++; }
            }

            DA.SetDataList(0, types);
            DA.SetData(1, flat);
            DA.SetData(2, bent);
            DA.SetData(3, custom);
        }
    }

