        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Total Area", "Sum", "Total area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Min Area", "Min", "Smallest area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Max Area", "Max", "Largest area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Mean Area", "Mean", "Mean area", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelAccess.GetPanels(DA, 0);
            if (panels.Count == 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "No panels");
