            }

            var areas = panels.Select(p => p.Area).ToList();
            DA.SetData(0, areas.Sum());
            DA.SetData(1, areas.Min());
            DA.SetData(2, areas.Max());
            DA.SetData(3, areas.Average());
        }
    }
