cat > Facade/FabricationComponents.cs <<'EOF'
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    public class GroupIdenticalPanelsComponent : GH_Component
    {
        public GroupIdenticalPanelsComponent()
            : base("Group Identical Panels", "Group", "Groups panels with matching edge and diagonal lengths", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("e8f3a1c4-7b25-4d90-8e16-5a9c2d4b6f66");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Maximum length difference", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddIntegerParameter("Group", "G", "Group number per panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Group Count", "N", "Number of groups", GH_ParamAccess.item);
            pManager.AddParameter(new PanelParam(), "Representatives", "R", "First panel of each group", GH_ParamAccess.list);
        }

        private static bool Close(double[] a, double[] b, double tol)
        {
            for (int i = 0; i < a.Length; i++)
                if (Math.Abs(a[i] - b[i]) > tol) return false;
            return true;
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelAccess.GetPanels(DA, 0);
            double tol = 1.0;
            if (!DA.GetData(1, ref tol)) return;

            var reps = new List<FacadePanel>();
            var repEdges = new List<double[]>();
            var repDiags = new List<double[]>();
            var group = new List<int>();

            foreach (var p in panels)
            {
                var e = p.SortedEdges();
                var d = p.SortedDiagonals();
                int found = -1;
                for (int g = 0; g < reps.Count && found < 0; g++)
                    if (Close(e, repEdges[g], tol) && Close(d, repDiags[g], tol)) found = g;
                if (found < 0)
                {
                    found = reps.Count;
                    reps.Add(p);
                    repEdges.Add(e);
                    repDiags.Add(d);
                }
                group.Add(found);
            }

            DA.SetDataList(0, group);
            DA.SetData(1, reps.Count);
            DA.SetDataList(2, PanelAccess.Wrap(reps));
        }
    }

    public class NestOnSheetsComponent : GH_Component
    {
        private class NestResult
        {
            public List<Curve> Outlines = new List<Curve>();
            public List<int> Sheets = new List<int>();
            public int SheetCount;
            public double Utilization;
            public int Unplaced;
        }

        private CancellationTokenSource _cts;
        private double[] _key;
        private NestResult _result;
        private volatile int _progress;

        public NestOnSheetsComponent()
            : base("Nest On Sheets", "Nest", "Nests panels as rectangles on sheets with a shelf algorithm", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("1a2b3c4d-5e6f-4a70-8b91-c2d3e4f50777");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddNumberParameter("Sheet Width", "W", "Sheet width", GH_ParamAccess.item, 3000.0);
            pManager.AddNumberParameter("Sheet Height", "H", "Sheet height", GH_ParamAccess.item, 1500.0);
            pManager.AddNumberParameter("Spacing", "S", "Gap between parts and from the sheet edge", GH_ParamAccess.item, 10.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddCurveParameter("Outlines", "O", "Placed rectangles", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet", "S", "Sheet index per placed panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet Count", "N", "Number of sheets used", GH_ParamAccess.item);
            pManager.AddNumberParameter("Utilization", "U", "Placed area / total sheet area", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelAccess.GetPanels(DA, 0);
            double sw = 3000, sh = 1500, sp = 10;
            if (!DA.GetData(1, ref sw)) return;
            if (!DA.GetData(2, ref sh)) return;
            if (!DA.GetData(3, ref sp)) return;

            var key = new List<double> { sw, sh, sp };
            foreach (var p in panels) { key.Add(p.Width); key.Add(p.Height); }
            var keyArr = key.ToArray();

            if (_key != null && _key.SequenceEqual(keyArr))
            {
                if (_result == null)
                {
                    Message = $"Nesting {_progress}%";
                    return;
                }
                Message = null;
                Output(DA, _result);
                return;
            }

            // Inputs changed: stop the old run and start a new one.
            _cts?.Cancel();
            var cts = new CancellationTokenSource();
            _cts = cts;
            _key = keyArr;
            _result = null;
            _progress = 0;
            Message = "Nesting 0%";

            var sizes = panels.Select(p => new[] { p.Width, p.Height }).ToList();
            Task.Run(() =>
            {
                NestResult res;
                try { res = Nest(sizes, sw, sh, sp, cts.Token); }
                catch (OperationCanceledException) { return; }
                if (cts.IsCancellationRequested) return;
                Rhino.RhinoApp.InvokeOnUiThread((Action)(() =>
                {
                    if (cts.IsCancellationRequested) return;
                    _result = res;
                    ExpireSolution(true);
                }));
            });
        }

        private void Output(IGH_DataAccess DA, NestResult r)
        {
            if (r.Unplaced > 0)
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning, $"{r.Unplaced} panels fit on no sheet");
            DA.SetDataList(0, r.Outlines);
            DA.SetDataList(1, r.Sheets);
            DA.SetData(2, r.SheetCount);
            DA.SetData(3, r.Utilization);
        }

        private NestResult Nest(List<double[]> sizes, double sw, double sh, double sp, CancellationToken ct)
        {
            var res = new NestResult();
            var order = Enumerable.Range(0, sizes.Count).OrderByDescending(i => sizes[i][1]).ToList();

            int sheet = -1;
            double shelfY = 0, shelfH = 0, cursorX = 0;
            bool haveShelf = false;
            double placedArea = 0;
            int lastReported = -1;

            for (int n = 0; n < order.Count; n++)
            {
                ct.ThrowIfCancellationRequested();
                int pct = (int)(100.0 * n / order.Count);
                if (pct != lastReported)
                {
                    lastReported = pct;
                    _progress = pct;
                    Message = $"Nesting {pct}%";
                    Grasshopper.Instances.RedrawCanvas();
                }

                double w = sizes[order[n]][0], h = sizes[order[n]][1];
                bool fitsEmpty = (w + 2 * sp <= sw && h + 2 * sp <= sh) || (h + 2 * sp <= sw && w + 2 * sp <= sh);
                if (!fitsEmpty) { res.Unplaced++; continue; }

                double px = 0, py = 0, pw = w, ph = h;
                bool placed = false;

                // 1. current shelf
                if (haveShelf)
                {
                    if (cursorX + w + sp <= sw && h <= shelfH) { pw = w; ph = h; placed = true; }
                    else if (cursorX + h + sp <= sw && w <= shelfH) { pw = h; ph = w; placed = true; }
                    if (placed) { px = cursorX; py = shelfY; }
                }

                // 2. new shelf on the current sheet
                if (!placed && haveShelf)
                {
                    double y = shelfY + shelfH + sp;
                    if (y + h + sp <= sh && w + 2 * sp <= sw) { pw = w; ph = h; placed = true; }
                    else if (y + w + sp <= sh && h + 2 * sp <= sw) { pw = h; ph = w; placed = true; }
                    if (placed) { shelfY = y; shelfH = ph; px = sp; py = y; }
                }

                // 3. new sheet
                if (!placed)
                {
                    sheet++;
                    if (w + 2 * sp <= sw && h + 2 * sp <= sh) { pw = w; ph = h; }
                    else { pw = h; ph = w; }
                    shelfY = sp; shelfH = ph; px = sp; py = sp;
                    haveShelf = true;
                }

                cursorX = px + pw + sp;
                double ox = sheet * (sw + 100);
                var pl = new Polyline(new[]
                {
                    new Point3d(ox + px, py, 0), new Point3d(ox + px + pw, py, 0),
                    new Point3d(ox + px + pw, py + ph, 0), new Point3d(ox + px, py + ph, 0),
                    new Point3d(ox + px, py, 0),
                });
                res.Outlines.Add(new PolylineCurve(pl));
                res.Sheets.Add(sheet);
                placedArea += pw * ph;
            }

            res.SheetCount = sheet + 1;
            res.Utilization = res.SheetCount > 0 ? placedArea / (res.SheetCount * sw * sh) : 0;
            return res;
        }

        protected override void BeforeSolveInstance()
        {
            if (Message != null && _result != null) Message = null;
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            _cts?.Cancel();
            base.RemovedFromDocument(document);
        }
    }

    public class CutListComponent : GH_Component
    {
        public CutListComponent()
            : base("Cut List", "Cut List", "Builds a CSV cut list and optionally writes it to disk", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("6d7e8f90-a1b2-4c3d-9e4f-5a6b7c8d9e88");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddTextParameter("Path", "Pa", "CSV file path", GH_ParamAccess.item, "");
            pManager.AddBooleanParameter("Write", "W", "Write the file", GH_ParamAccess.item, false);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("CSV", "CSV", "Cut list", GH_ParamAccess.item);
            pManager.AddBooleanParameter("Written", "W", "True when the file was written", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelAccess.GetPanels(DA, 0);
            string path = "";
            bool write = false;
            DA.GetData(1, ref path);
            DA.GetData(2, ref write);

            var ic = CultureInfo.InvariantCulture;
            var sb = new StringBuilder("index,width,height,area,deviation\n");
            foreach (var p in panels)
                sb.Append(p.Index.ToString(ic)).Append(',')
                  .Append(p.Width.ToString("0.###", ic)).Append(',')
                  .Append(p.Height.ToString("0.###", ic)).Append(',')
                  .Append(p.Area.ToString("0.###", ic)).Append(',')
                  .Append(p.Deviation.ToString("0.###", ic)).Append('\n');
            string csv = sb.ToString();

            bool written = false;
            if (write)
            {
                if (string.IsNullOrWhiteSpace(path))
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Path is empty");
                else
                {
                    try { File.WriteAllText(path, csv); written = true; }
                    catch (Exception ex) { AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Could not write file: " + ex.Message); }
                }
            }

            DA.SetData(0, csv);
            DA.SetData(1, written);
        }
    }
}
